    fn aliases(statement: &Statement, selected: Public<'_>) -> bool {
        match (statement, selected) {
            (Statement::PrivateTransfer { common, public }, Public::Transfer(p, lane)) =>
                core::ptr::eq(p, public) && core::ptr::eq(lane, &common.lane_transition),
            (Statement::Withdrawal { common, public }, Public::Withdrawal(p, lane)) =>
                core::ptr::eq(p, public) && core::ptr::eq(lane, &common.lane_transition),
            _ => false,
        }
    }

    #[kani::proof]
    #[kani::unwind(8)]
    fn boxed_semantic_borrows_same_statement() {
        // Safe scalar constructors initialize every field; no transmute,
        // byte-layout premise, canonicality premise, decoder or getter stub.
        let statement = Box::new(arbitrary_statement());
        match &*statement {
            Statement::PrivateTransfer { common, public } => {
                assert!(core::ptr::eq(statement.common(), common));
                assert!(core::ptr::eq(statement.nullifier(), &public.nullifier));
                kani::cover!(true, "transfer native box reached");
            }
            Statement::Withdrawal { common, public } => {
                assert!(core::ptr::eq(statement.common(), common));
                assert!(core::ptr::eq(statement.nullifier(), &public.nullifier));
                kani::cover!(true, "withdrawal native box reached");
            }
        }
        let selected = statement.semantic_public();
        assert!(aliases(&statement, selected));
        // Both immutable borrows remain live in the call; selected is used
        // before its owner is dropped by ordinary Rust Box cleanup.
        assert!(aliases(&statement, statement.semantic_public()));
    }

    #[kani::proof]
    #[kani::unwind(8)]
    fn wrong_box_negative_control() {
        let statement = Box::new(arbitrary_statement());
        let other = Box::new(*statement);
        // Same native values, distinct live owner: this assertion MUST fail.
        assert!(aliases(&statement, other.semantic_public()));
    }
